class Player {
    _money;
    _level;
    _energy;
    _hunger;
    constructor() {
        this._level = 0;
        this._money = 0;
        this._energy = 16;
        this._hunger = 0;
    }
    getMoney() {
        return this._money;
    }
    addMoney(money) {
        this._money += money;
    }
    setMoney(money) {
        this._money = money;
    }
    getEnergy() {
        return this._energy;
    }
    subEnergy(energy) {
        if (this._energy < energy) {
            throw new Error('Не хватает энергии');
        }
        this._energy -= energy;
    }
    addEnergy(energy) {
        this._energy += energy;
    }
    getHunger() {
        return this._hunger;
    }
    addHungre(hungre) {
        this._hunger += hungre;
    }
    subHungre(hungre) {
        this._hunger -= hungre;
    }
    addLevel(level) {
        this._level += level;
    }
    getLevel() {
        return this._level;
    }
}
export default Player;
